  2498  void Mle::HandleUdpReceive(Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
  2499  {
  2500      ThreadNetif &   netif      = GetNetif();
  2501      KeyManager &    keyManager = netif.GetKeyManager();
  2502      MleRouter &     mle        = netif.GetMle();
  2503      Header          header;
  2504      uint32_t        keySequence;
  2505      const uint8_t * mleKey;
  2506      uint32_t        frameCounter;
  2507      uint8_t         messageTag[4];
  2508      uint8_t         nonce[13];
  2509      Mac::ExtAddress macAddr;
  2510      Crypto::AesCcm  aesCcm;
  2511      uint16_t        mleOffset;
  2512      uint8_t         buf[64];
  2513      uint16_t        length;
  2514      uint8_t         tag[4];
  2515      uint8_t         tagLength;
  2516      uint8_t         command;
  2517      Neighbor *      neighbor;
  2518
  2519      VerifyOrExit(aMessageInfo.GetLinkInfo() != NULL);
  2520      VerifyOrExit(aMessageInfo.GetHopLimit() == kMleHopLimit);
  2521
  2522      length = aMessage.Read(aMessage.GetOffset(), sizeof(header), &header);
  2523      VerifyOrExit(header.IsValid() && header.GetLength() <= length);
  2524
  2525      if (header.GetSecuritySuite() == Header::kNoSecurity)
  2526      {
  2527          aMessage.MoveOffset(header.GetLength());
  2528
  2529          switch (header.GetCommand())
  2530          {
  2531          case Header::kCommandDiscoveryRequest:
  2532              mle.HandleDiscoveryRequest(aMessage, aMessageInfo);
  2533              break;
  2534
  2535          case Header::kCommandDiscoveryResponse:
  2536              HandleDiscoveryResponse(aMessage, aMessageInfo);
  2537              break;
  2538
  2539          default:
  2540              break;
  2541          }
  2542
  2543          ExitNow();
  2544      }
  2545
  2546      VerifyOrExit(mRole != OT_DEVICE_ROLE_DISABLED && header.GetSecuritySuite() == Header::k154Security);
  2547
  2548      keySequence = header.GetKeyId();
  2549
  2550      if (keySequence == keyManager.GetCurrentKeySequence())
  2551      {
  2552          mleKey = keyManager.GetCurrentMleKey();
  2553      }
  2554      else
  2555      {
  2556          mleKey = keyManager.GetTemporaryMleKey(keySequence);
  2557      }
  2558
  2559      VerifyOrExit(aMessage.GetOffset() + header.GetLength() + sizeof(messageTag) <= aMessage.GetLength());
  2560      aMessage.MoveOffset(header.GetLength() - 1);
  2561
  2562      aMessage.Read(aMessage.GetLength() - sizeof(messageTag), sizeof(messageTag), messageTag);
  2563      SuccessOrExit(aMessage.SetLength(aMessage.GetLength() - sizeof(messageTag)));
  2564
  2565      aMessageInfo.GetPeerAddr().ToExtAddress(macAddr);
  2566      frameCounter = header.GetFrameCounter();
  2567      GenerateNonce(macAddr, frameCounter, Mac::Frame::kSecEncMic32, nonce);
  2568
  2569      aesCcm.SetKey(mleKey, 16);
  2570      SuccessOrExit(
  2571          aesCcm.Init(sizeof(aMessageInfo.GetPeerAddr()) + sizeof(aMessageInfo.GetSockAddr()) + header.GetHeaderLength(),
  2572                      aMessage.GetLength() - aMessage.GetOffset(), sizeof(messageTag), nonce, sizeof(nonce)));
  2573
  2574      aesCcm.Header(&aMessageInfo.GetPeerAddr(), sizeof(aMessageInfo.GetPeerAddr()));
  2575      aesCcm.Header(&aMessageInfo.GetSockAddr(), sizeof(aMessageInfo.GetSockAddr()));
  2576      aesCcm.Header(header.GetBytes() + 1, header.GetHeaderLength());
  2577
  2578      mleOffset = aMessage.GetOffset();
  2579
  2580      while (aMessage.GetOffset() < aMessage.GetLength())
  2581      {
  2582          length = aMessage.Read(aMessage.GetOffset(), sizeof(buf), buf);
  2583          aesCcm.Payload(buf, buf, length, false);
  2584  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  2585          aMessage.Write(aMessage.GetOffset(), length, buf);
  2586  #endif
  2587          aMessage.MoveOffset(length);
  2588      }
  2588      }
  2589
  2590      tagLength = sizeof(tag);
  2591      aesCcm.Finalize(tag, &tagLength);
  2592  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  2593      VerifyOrExit(memcmp(messageTag, tag, sizeof(tag)) == 0);
  2594  #endif
  2595
  2596      if (keySequence > keyManager.GetCurrentKeySequence())
  2597      {
  2598          keyManager.SetCurrentKeySequence(keySequence);
  2599      }
  2600
  2601      aMessage.SetOffset(mleOffset);
  2602
  2603      aMessage.Read(aMessage.GetOffset(), sizeof(command), &command);
  2604      aMessage.MoveOffset(sizeof(command));
  2605
  2606      switch (mRole)
  2607      {
  2608      case OT_DEVICE_ROLE_DETACHED:
  2609      case OT_DEVICE_ROLE_CHILD:
  2610          neighbor = GetNeighbor(macAddr);
  2611          break;
  2612
  2613      case OT_DEVICE_ROLE_ROUTER:
  2614      case OT_DEVICE_ROLE_LEADER:
  2615          if (command == Header::kCommandChildIdResponse)
  2616          {
  2617              neighbor = GetNeighbor(macAddr);
  2618          }
  2619          else
  2620          {
  2621              neighbor = mle.GetNeighbor(macAddr);
  2622          }
  2623
  2624          break;
  2625
  2626      default:
  2627          neighbor = NULL;
  2628          break;
  2629      }
  2630
  2631      if (neighbor != NULL && neighbor->GetState() == Neighbor::kStateValid)
  2632      {
  2633          if (keySequence == neighbor->GetKeySequence())
  2634          {
  2635              if (frameCounter < neighbor->GetMleFrameCounter())
  2636              {
  2637                  otLogDebgMle("mle frame reject 1");
  2638                  ExitNow();
  2639              }
  2640          }
  2641          else
  2642          {
  2643              if (keySequence <= neighbor->GetKeySequence())
  2644              {
  2645                  otLogDebgMle("mle frame reject 2");
  2646                  ExitNow();
  2647              }
  2648
  2649              neighbor->SetKeySequence(keySequence);
  2650              neighbor->SetLinkFrameCounter(0);
  2651          }
  2652
  2653          neighbor->SetMleFrameCounter(frameCounter + 1);
  2654      }
  2655      else
  2656      {
  2657          if (!(command == Header::kCommandLinkRequest || command == Header::kCommandLinkAccept ||
  2658                command == Header::kCommandLinkAcceptAndRequest || command == Header::kCommandAdvertisement ||
  2659                command == Header::kCommandParentRequest || command == Header::kCommandParentResponse ||
  2660                command == Header::kCommandChildIdRequest || command == Header::kCommandChildUpdateRequest ||
  2661                command == Header::kCommandChildUpdateResponse || command == Header::kCommandAnnounce))
  2662          {
  2663              otLogDebgMle("mle sequence unknown! %d", command);
  2664              ExitNow();
  2665          }
  2665          }
  2666      }
  2667
  2668      switch (command)
  2669      {
  2670      case Header::kCommandLinkRequest:
  2671          mle.HandleLinkRequest(aMessage, aMessageInfo);
  2672          break;
  2673
  2674      case Header::kCommandLinkAccept:
  2675          mle.HandleLinkAccept(aMessage, aMessageInfo, keySequence);
  2676          break;
  2677
  2678      case Header::kCommandLinkAcceptAndRequest:
  2679          mle.HandleLinkAcceptAndRequest(aMessage, aMessageInfo, keySequence);
  2680          break;
  2681
  2682      case Header::kCommandAdvertisement:
  2683          HandleAdvertisement(aMessage, aMessageInfo);
  2684          break;
  2685
  2686      case Header::kCommandDataRequest:
  2687          mle.HandleDataRequest(aMessage, aMessageInfo);
  2688          break;
  2689
  2690      case Header::kCommandDataResponse:
  2691          HandleDataResponse(aMessage, aMessageInfo);
  2692          break;
  2693
  2694      case Header::kCommandParentRequest:
  2695          mle.HandleParentRequest(aMessage, aMessageInfo);
  2696          break;
  2697
  2698      case Header::kCommandParentResponse:
  2699          HandleParentResponse(aMessage, aMessageInfo, keySequence);
  2700          break;
  2701
  2702      case Header::kCommandChildIdRequest:
  2703          mle.HandleChildIdRequest(aMessage, aMessageInfo, keySequence);
  2704          break;
  2705
  2706      case Header::kCommandChildIdResponse:
  2707          HandleChildIdResponse(aMessage, aMessageInfo);
  2708          break;
  2709
  2710      case Header::kCommandChildUpdateRequest:
  2711          if (mRole == OT_DEVICE_ROLE_LEADER || mRole == OT_DEVICE_ROLE_ROUTER)
  2712          {
  2713              mle.HandleChildUpdateRequest(aMessage, aMessageInfo, keySequence);
  2714          }
  2715          else
  2716          {
  2717              HandleChildUpdateRequest(aMessage, aMessageInfo);
  2718          }
  2719
  2720          break;
  2721
  2722      case Header::kCommandChildUpdateResponse:
  2723          if (mRole == OT_DEVICE_ROLE_LEADER || mRole == OT_DEVICE_ROLE_ROUTER)
  2724          {
  2725              mle.HandleChildUpdateResponse(aMessage, aMessageInfo, keySequence);
  2726          }
  2727          else
  2728          {
  2729              HandleChildUpdateResponse(aMessage, aMessageInfo);
  2730          }
  2731
  2732          break;
  2733
  2734      case Header::kCommandAnnounce:
  2735          HandleAnnounce(aMessage, aMessageInfo);
  2736          break;
  2737
  2738  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
  2739      case Header::kCommandTimeSync:
  2740          mle.HandleTimeSync(aMessage, aMessageInfo);
  2741          break;
  2742  #endif
  2743      }
  2744
  2745  exit:
  2746      return;
  2747  }
